(()=>{'use strict';const ID='lw-3d-globe';if(window.__lwGlobeStandalone)return;window.__lwGlobeStandalone=true;
const css=document.createElement('style');css.textContent=`#${ID}{position:relative;min-height:520px;border-radius:14px;overflow:hidden;background:radial-gradient(ellipse at center,#132b61,#060e2a);color:#fff;isolation:isolate}#${ID} canvas{display:block;width:100%;height:460px;touch-action:pan-y;cursor:grab}#${ID} .title{position:absolute;left:20px;top:17px;z-index:2;font-size:21px;font-weight:700;pointer-events:none}#${ID} .legend{padding:12px 16px;margin:0 14px 14px;border:1px solid #667ea8;border-radius:9px;background:#0b1a3b;color:#fff;font-size:14px;overflow-wrap:anywhere}#${ID} button{position:absolute;right:15px;top:15px;z-index:3;background:#1b396d;color:#fff;border:1px solid #b6c8eb;padding:8px 12px;border-radius:8px;cursor:pointer}#${ID} button:focus-visible{outline:3px solid #ffd13c}@media(max-width:600px){#${ID} canvas{height:340px}#${ID}{min-height:400px}#${ID} .title{font-size:15px;top:18px}}`;document.head.append(css);
const cities=[['Шэньчжэнь',22.5431,114.0579],['Нинбо',29.8683,121.544],['Минск',53.9006,27.559]];
let mounted=null;function mount(){const heading=[...document.querySelectorAll('h1,h2,h3,h4,strong')].find(e=>e.textContent.trim()==='Живая карта логистики');if(!heading)return;const section=heading.closest('section,article')||heading.parentElement?.parentElement;if(!section||section.querySelector('#'+ID))return;const frames=[...section.querySelectorAll('iframe')];const frame=frames.find(x=>/map|yandex/i.test(x.src||''))||frames[0];const mapNode=frame||[...section.querySelectorAll('div')].find(x=>x!==section&&x.clientHeight>250&&x.clientWidth>300&&(/map|карта/i.test(x.className?.toString()||'')));if(!mapNode)return;
const text=section.textContent||'';if(!/Шэньчжэнь|Нинбо|Минск/.test(text))return;const pts=[cities[0],...(text.includes('Нинбо')?[cities[1]]:[]),cities[2]];const host=document.createElement('div');host.id=ID;host.innerHTML='<div class="title">3D · Глобус маршрута</div><button type="button">Показать 2D</button><canvas aria-label="Вращаемый глобус: Китай — Минск"></canvas><div class="legend"></div>';host.querySelector('.legend').textContent=pts.map((p,i)=>(i+1)+'. '+p[0]).join(' → ')+' · Схематическая визуализация, не точная железнодорожная трасса';mapNode.before(host);mapNode.style.display='none';host.querySelector('button').onclick=()=>{mapNode.style.display='';host.remove();mounted=null};mounted=host;
const canvas=host.querySelector('canvas'),ctx=canvas.getContext('2d');if(!ctx){mapNode.style.display='';host.remove();return}let yaw=70,pitch=35,zoom=1,down=false,lastX=0,lastY=0;const rad=Math.PI/180;
function project(lat,lon,R,cx,cy){const a=lat*rad,b=(lon-yaw)*rad,p=pitch*rad;const x=Math.cos(a)*Math.sin(b),z=Math.cos(a)*Math.cos(b),y=Math.sin(a);return {x:cx+R*x,y:cy-R*(y*Math.cos(p)-z*Math.sin(p)),visible:z*Math.cos(p)+y*Math.sin(p)>0}}
function draw(){if(!host.isConnected)return;const rect=canvas.getBoundingClientRect(),w=Math.max(250,rect.width),h=Math.max(260,rect.height),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const R=Math.min(w*.42,h*.44)*zoom,cx=w/2,cy=h/2+18;const glow=ctx.createRadialGradient(cx,cy,R*.4,cx,cy,R*1.35);glow.addColorStop(0,'#123d7c');glow.addColorStop(.7,'#173e7c');glow.addColorStop(1,'#07132d');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(cx,cy,R*1.18,0,Math.PI*2);ctx.fill();const ocean=ctx.createRadialGradient(cx-R*.3,cy-R*.4,R*.04,cx,cy,R);ocean.addColorStop(0,'#4384bd');ocean.addColorStop(.65,'#17497d');ocean.addColorStop(1,'#08182d');ctx.fillStyle=ocean;ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.fill();ctx.save();ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.clip();
ctx.strokeStyle='rgba(135,188,239,.24)';ctx.lineWidth=.8;for(let lat=-75;lat<=75;lat+=15){ctx.beginPath();let started=false;for(let lon=-180;lon<=180;lon+=3){const p=project(lat,lon,R,cx,cy);if(!p.visible){started=false;continue}if(!started){ctx.moveTo(p.x,p.y);started=true}else ctx.lineTo(p.x,p.y)}ctx.stroke()}for(let lon=-180;lon<180;lon+=15){ctx.beginPath();let started=false;for(let lat=-90;lat<=90;lat+=3){const p=project(lat,lon,R,cx,cy);if(!p.visible){started=false;continue}if(!started){ctx.moveTo(p.x,p.y);started=true}else ctx.lineTo(p.x,p.y)}ctx.stroke()}
ctx.strokeStyle='#ffcb36';ctx.lineWidth=3;ctx.beginPath();let started=false;for(let i=0;i<pts.length-1;i++){for(let j=0;j<=70;j++){const t=j/70,lat=pts[i][1]*(1-t)+pts[i+1][1]*t,lon=pts[i][2]*(1-t)+pts[i+1][2]*t,p=project(lat,lon,R,cx,cy);if(!p.visible){started=false;continue}if(!started){ctx.moveTo(p.x,p.y);started=true}else ctx.lineTo(p.x,p.y)}}ctx.stroke();for(const p of pts){const q=project(p[1],p[2],R,cx,cy);if(!q.visible)continue;ctx.fillStyle='#ffd23d';ctx.beginPath();ctx.arc(q.x,q.y,5,0,Math.PI*2);ctx.fill();ctx.font='bold 13px system-ui';ctx.fillStyle='#fff';ctx.shadowColor='#000';ctx.shadowBlur=5;ctx.fillText(p[0],q.x+10,q.y-9);ctx.shadowBlur=0}ctx.restore();ctx.strokeStyle='#77b8f5';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.stroke()}
canvas.addEventListener('pointerdown',e=>{down=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointerup',()=>down=false);canvas.addEventListener('pointermove',e=>{if(!down)return;yaw-=(e.clientX-lastX)*.4;pitch=Math.max(-80,Math.min(80,pitch+(e.clientY-lastY)*.25));lastX=e.clientX;lastY=e.clientY;draw()});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.6,Math.min(1.4,zoom-e.deltaY*.001));draw()},{passive:false});if(window.ResizeObserver)new ResizeObserver(()=>{if(host.isConnected)draw()}).observe(canvas);draw()}
new MutationObserver(()=>{if(!mounted||!mounted.isConnected)mount()}).observe(document.body,{childList:true,subtree:true});mount()})();